public class ContactDomainService {

    /**
     * Groups contacts belonging to the given accounts by the lower-cased domain
     * portion of their email address (e.g. "Jane@Example.COM" -> "example.com").
     *
     * @param accountIds IDs of the accounts whose contacts should be grouped.
     * @return A map keyed by email domain to a list of Contact records. Each
     *         contact has Id, Email, and AccountId populated. Contacts without
     *         an email are excluded. Returns an empty map for a null or empty
     *         input set. Enforces the running user's sharing.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> groupedByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return groupedByDomain;
        }

        Set<Id> filteredAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                filteredAccountIds.add(accountId);
            }
        }

        if (filteredAccountIds.isEmpty()) {
            return groupedByDomain;
        }

        for (Contact contact : [
                SELECT Id, Email, AccountId
                FROM Contact
                WHERE AccountId IN :filteredAccountIds
                AND Email != null
            ]) {
            String email = contact.Email;
            if (String.isBlank(email)) {
                continue;
            }

            String[] emailParts = email.split('@');
            String domain = emailParts[emailParts.size() - 1].trim().toLowerCase();

            if (String.isBlank(domain)) {
                continue;
            }

            List<Contact> contactsForDomain = groupedByDomain.get(domain);
            if (contactsForDomain == null) {
                contactsForDomain = new List<Contact>();
                groupedByDomain.put(domain, contactsForDomain);
            }
            contactsForDomain.add(contact);
        }

        return groupedByDomain;
    }
}
