public class OrderPayloadParser {

    public class PayloadException extends Exception {
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        try {
            if (body == null || body.trim().isEmpty()) {
                throw new PayloadException('Order payload body is null or blank.');
            }

            JSONParser parser = JSON.createParser(body);

            JSONToken token = parser.nextToken();
            if (token != JSONToken.START_OBJECT) {
                throw new PayloadException('Order payload must be a JSON object.');
            }

            String orderNumber = null;
            Date orderDate = null;
            String currencyCode = null;
            String customerEmail = null;
            List<Line> lines = new List<Line>();

            Boolean objectClosed = false;
            while ((token = parser.nextToken()) != null) {
                if (token == JSONToken.END_OBJECT) {
                    objectClosed = true;
                    break;
                }
                if (token != JSONToken.FIELD_NAME) {
                    continue;
                }

                String fieldName = parser.getCurrentName();
                parser.nextToken(); // advance to the field value

                if ('number'.equals(fieldName)) {
                    if (parser.getCurrentToken() == JSONToken.VALUE_STRING) {
                        orderNumber = parser.getText();
                    } else {
                        skipValue(parser);
                    }
                } else if ('date'.equals(fieldName)) {
                    if (parser.getCurrentToken() == JSONToken.VALUE_STRING) {
                        try {
                            orderDate = Date.valueOf(parser.getText());
                        } catch (Exception ex) {
                            throw new PayloadException('Invalid order date: ' + parser.getText(), ex);
                        }
                    } else {
                        skipValue(parser);
                    }
                } else if ('currency'.equals(fieldName)) {
                    if (parser.getCurrentToken() == JSONToken.VALUE_STRING) {
                        currencyCode = parser.getText();
                    } else {
                        skipValue(parser);
                    }
                } else if ('customer'.equals(fieldName)) {
                    if (parser.getCurrentToken() == JSONToken.START_OBJECT) {
                        customerEmail = readCustomerEmail(parser);
                    } else {
                        skipValue(parser);
                    }
                } else if ('lines'.equals(fieldName)) {
                    if (parser.getCurrentToken() == JSONToken.START_ARRAY) {
                        lines = readLines(parser);
                    } else {
                        skipValue(parser);
                    }
                } else {
                    skipValue(parser);
                }
            }

            if (!objectClosed) {
                throw new PayloadException('Invalid JSON: order object was not closed.');
            }

            if (orderNumber == null || orderNumber.trim().isEmpty()) {
                throw new PayloadException('Order number is missing or blank.');
            }

            Decimal total = 0;
            for (Line line : lines) {
                total += line.lineTotal;
            }

            Order order = new Order();
            order.orderNumber = orderNumber;
            order.orderDate = orderDate;
            order.currencyCode = currencyCode;
            order.customerEmail = customerEmail;
            order.lines = lines;
            order.total = total;
            return order;
        } catch (PayloadException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new PayloadException('Failed to parse order payload: ' + ex.getMessage(), ex);
        }
    }

    private static String readCustomerEmail(JSONParser parser) {
        String email = null;
        JSONToken token;
        while ((token = parser.nextToken()) != null) {
            if (token == JSONToken.END_OBJECT) {
                break;
            }
            if (token != JSONToken.FIELD_NAME) {
                continue;
            }
            String name = parser.getCurrentName();
            parser.nextToken(); // advance to value
            if ('email'.equals(name)) {
                if (parser.getCurrentToken() == JSONToken.VALUE_STRING) {
                    email = parser.getText();
                } else {
                    skipValue(parser);
                }
            } else {
                skipValue(parser);
            }
        }
        return email;
    }

    private static List<Line> readLines(JSONParser parser) {
        List<Line> result = new List<Line>();
        JSONToken token;
        while ((token = parser.nextToken()) != null) {
            if (token == JSONToken.END_ARRAY) {
                break;
            }
            if (token == JSONToken.START_OBJECT) {
                result.add(readLine(parser));
            } else {
                skipValue(parser);
            }
        }
        return result;
    }

    private static Line readLine(JSONParser parser) {
        Line line = new Line();

        String sku = null;
        Decimal quantity = null;
        Decimal unitPrice = null;
        Decimal discount = 0;

        JSONToken token;
        while ((token = parser.nextToken()) != null) {
            if (token == JSONToken.END_OBJECT) {
                break;
            }
            if (token != JSONToken.FIELD_NAME) {
                continue;
            }

            String name = parser.getCurrentName();
            parser.nextToken(); // advance to value

            if ('sku'.equals(name)) {
                if (parser.getCurrentToken() == JSONToken.VALUE_STRING) {
                    sku = parser.getText();
                } else {
                    skipValue(parser);
                }
            } else if ('quantity'.equals(name)) {
                quantity = readNumberOrNull(parser);
            } else if ('unitPrice'.equals(name)) {
                unitPrice = readNumberOrNull(parser);
            } else if ('discount'.equals(name)) {
                Decimal d = readNumberOrNull(parser);
                discount = (d == null) ? 0 : d;
            } else {
                skipValue(parser);
            }
        }

        if (sku == null || sku.trim().isEmpty()) {
            throw new PayloadException('Order line is missing a valid sku.');
        }
        if (quantity == null) {
            throw new PayloadException('Order line is missing quantity.');
        }
        if (quantity <= 0) {
            throw new PayloadException('Order line quantity must be positive.');
        }
        if (unitPrice == null) {
            throw new PayloadException('Order line is missing unitPrice.');
        }
        if (unitPrice < 0) {
            throw new PayloadException('Order line unitPrice must be non-negative.');
        }

        line.sku = sku;
        line.quantity = quantity.intValue();
        line.unitPrice = unitPrice;
        line.discount = discount;
        line.lineTotal = (quantity * unitPrice * (1 - discount)).setScale(2, RoundingMode.HALF_UP);
        return line;
    }

    private static Decimal readNumberOrNull(JSONParser parser) {
        JSONToken token = parser.getCurrentToken();
        if (token == JSONToken.VALUE_NUMBER_INT || token == JSONToken.VALUE_NUMBER_FLOAT) {
            return parser.getDecimalValue();
        }
        return null;
    }

    private static void skipValue(JSONParser parser) {
        JSONToken token = parser.getCurrentToken();
        if (token == JSONToken.START_OBJECT) {
            while ((token = parser.nextToken()) != null) {
                if (token == JSONToken.END_OBJECT) {
                    return;
                }
                if (token == JSONToken.FIELD_NAME) {
                    parser.nextToken();
                    skipValue(parser);
                }
            }
        } else if (token == JSONToken.START_ARRAY) {
            while ((token = parser.nextToken()) != null) {
                if (token == JSONToken.END_ARRAY) {
                    return;
                }
                skipValue(parser);
            }
        }
        // Scalar (or null): nothing further to consume.
    }

    public static String toAcknowledgement(Order order) {
        Integer lineCount = (order == null || order.lines == null) ? 0 : order.lines.size();
        Decimal total = (order == null || order.total == null) ? 0 : order.total;
        String number = (order == null) ? null : order.orderNumber;

        JSONGenerator generator = JSON.createGenerator(false);
        generator.writeStartObject();
        generator.writeStringField('number', number);
        generator.writeStringField('status', 'RECEIVED');
        generator.writeNumberField('lineCount', lineCount);
        generator.writeNumberField('total', total);
        generator.writeEndObject();
        return generator.getAsString();
    }
}
