@isTest
private class ShippingCostCalculatorTest {

    //----------------------------------------------------------------------
    // Helpers
    //----------------------------------------------------------------------
    private static void expectShippingException(
        Decimal weightKg,
        String zone,
        Boolean express,
        Decimal orderValue
    ) {
        try {
            ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
            System.fail('Expected ShippingCostCalculator.ShippingException was not thrown.');
        } catch (ShippingCostCalculator.ShippingException expected) {
            // Expected outcome.
        }
    }

    private static void assertQuote(
        Decimal expected,
        Decimal weightKg,
        String zone,
        Boolean express,
        Decimal orderValue
    ) {
        Decimal actual = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        System.assertEquals(
            expected,
            actual,
            'Unexpected quote for weight=' + String.valueOf(weightKg) +
            ', zone=' + String.valueOf(zone) +
            ', express=' + String.valueOf(express) +
            ', orderValue=' + String.valueOf(orderValue) + '.'
        );
    }

    //----------------------------------------------------------------------
    // Weight validation
    //----------------------------------------------------------------------
    @isTest
    static void weightMustBeGreaterThanZero() {
        expectShippingException(null, 'DOMESTIC', false, null);
        expectShippingException(0, 'DOMESTIC', false, null);
        expectShippingException(-0.01, 'DOMESTIC', false, null);
        expectShippingException(-100, 'EU', true, 200);

        // A weight greater than zero (even a tiny one) is accepted.
        assertQuote(5.00, 0.001, 'DOMESTIC', false, null);
    }

    //----------------------------------------------------------------------
    // Weight tiers and boundaries (domestic, standard)
    //----------------------------------------------------------------------
    @isTest
    static void weightTiersDomesticStandard() {
        // Tier boundaries inclusive at the top.
        assertQuote(5.00,   1,     'DOMESTIC', false, null);   // top of first tier
        assertQuote(9.50,   1.001, 'DOMESTIC', false, null);   // just above 1 kg
        assertQuote(9.50,   5,     'DOMESTIC', false, null);   // top of second tier
        assertQuote(18.00,  5.001, 'DOMESTIC', false, null);   // just above 5 kg
        assertQuote(18.00,  20,    'DOMESTIC', false, null);   // top of third tier

        // Above 20 kg: 0.75 per started kilogram over 20.
        assertQuote(18.75, 20.001, 'DOMESTIC', false, null);   // one started kg above 20
        assertQuote(18.75, 20.1,   'DOMESTIC', false, null);   // documented: 20.1 kg -> 18.75
        assertQuote(18.75, 21,     'DOMESTIC', false, null);   // one started kg above 20
        assertQuote(19.50, 21.001, 'DOMESTIC', false, null);   // two started kg above 20
        assertQuote(19.50, 22,     'DOMESTIC', false, null);   // two started kg above 20
    }

    //----------------------------------------------------------------------
    // Zones (case-insensitive) and invalid zones
    //----------------------------------------------------------------------
    @isTest
    static void zoneFactorsAreCaseInsensitive() {
        assertQuote(5.00,  1, 'DOMESTIC', false, null);
        assertQuote(5.00,  1, 'Domestic', false, null);
        assertQuote(5.00,  1, 'domestic', false, null);

        assertQuote(7.00,  1, 'EU', false, null);
        assertQuote(7.00,  1, 'Eu', false, null);
        assertQuote(7.00,  1, 'eu', false, null);

        assertQuote(11.00, 1, 'WORLD', false, null);
        assertQuote(11.00, 1, 'World', false, null);
        assertQuote(11.00, 1, 'world', false, null);
    }

    @isTest
    static void invalidZoneThrows() {
        expectShippingException(1, null, false, null);
        expectShippingException(1, '', false, null);
        expectShippingException(1, 'INVALID', false, null);
        expectShippingException(1, 'us', false, null);
        expectShippingException(1, 'Domestic ', false, null); // trailing space is not an exact match
    }

    //----------------------------------------------------------------------
    // Express flag
    //----------------------------------------------------------------------
    @isTest
    static void expressAddsFiftyPercent() {
        // null and false both mean standard delivery.
        assertQuote(5.00,  1, 'DOMESTIC', null,  null);
        assertQuote(5.00,  1, 'DOMESTIC', false, null);
        assertQuote(7.50,  1, 'DOMESTIC', true,  null); // 5.00 * 1.5

        assertQuote(19.95, 5, 'EU', true, null);        // 9.50 * 1.4 * 1.5
        assertQuote(59.40, 20, 'WORLD', true, null);    // 18.00 * 2.2 * 1.5
    }

    //----------------------------------------------------------------------
    // Free domestic standard shipping
    //----------------------------------------------------------------------
    @isTest
    static void domesticStandardFreeShippingThreshold() {
        // Exactly 100.00 qualifies; the benefit is weight independent.
        assertQuote(0.00, 1,   'DOMESTIC', false, 100);
        assertQuote(0.00, 25,  'DOMESTIC', false, 100.00);

        // Null express is standard, so it still qualifies.
        assertQuote(0.00, 1,   'DOMESTIC', null,  100);

        // Below the threshold is not free.
        assertQuote(5.00, 1,   'DOMESTIC', false, 99.99);

        // Null order value does not qualify.
        assertQuote(5.00, 1,   'DOMESTIC', false, null);

        // Express orders never qualify, even over the threshold.
        assertQuote(7.50, 1,   'DOMESTIC', true,  100);

        // Other zones never qualify, even over the threshold.
        assertQuote(7.00, 1,   'EU', false, 100);
        assertQuote(11.00, 1,  'WORLD', false, 100);
    }

    //----------------------------------------------------------------------
    // Rounding (half up, 2 decimals)
    //----------------------------------------------------------------------
    @isTest
    static void roundingHalfUpTwoDecimals() {
        // Documented example: 21 kg DOMESTIC express = 28.13 (28.125 rounds up).
        assertQuote(28.13, 21, 'DOMESTIC', true, null);

        // 39.375 -> 39.38.
        assertQuote(39.38, 20.1, 'EU', true, null);

        // 42.525 -> 42.53 (distinguishes HALF_UP from HALF_EVEN, which would give 42.52).
        assertQuote(42.53, 22.1, 'EU', true, null);

        // Clean values remain unchanged.
        assertQuote(11.00, 1, 'WORLD', false, null);
        assertQuote(25.20, 20, 'EU', false, null);
    }
}
