@IsTest
public class OpportunityWonHandlerTest {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String STAGE_PROSPECTING = 'Prospecting';
    private static final String NEXT_STEP_HANDOVER = 'Handover to Customer Success';
    private static final String TASK_SUBJECT = 'Customer kick-off';
    private static final String TASK_PRIORITY = 'High';

    @TestSetup
    static void testSetup() {
        insert new Account(Name = 'Warm Account', Rating = 'Warm');
        insert new Account(Name = 'Hot Account', Rating = 'Hot');
    }

    private static Id getWarmAccountId() {
        return [SELECT Id FROM Account WHERE Rating = 'Warm' LIMIT 1].Id;
    }

    private static Id getHotAccountId() {
        return [SELECT Id FROM Account WHERE Rating = 'Hot' LIMIT 1].Id;
    }

    private static Opportunity newOpportunity(Id accountId, String stageName, Date closeDate) {
        return new Opportunity(
            Name = 'Test Opportunity',
            StageName = stageName,
            CloseDate = closeDate,
            AccountId = accountId,
            OwnerId = UserInfo.getUserId()
        );
    }

    @IsTest
    static void testInsertWonOpportunitySetsNextStepTaskAndAccountRating() {
        Id accountId = getWarmAccountId();
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(accountId, STAGE_CLOSED_WON, closeDate);

        Test.startTest();
        insert opp;
        Test.stopTest();

        Opportunity persisted = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(NEXT_STEP_HANDOVER, persisted.NextStep,
            'NextStep must be set on a newly won insert');

        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority
                            FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task must be created');
        Task task = tasks[0];
        System.assertEquals(TASK_SUBJECT, task.Subject);
        System.assertEquals(opp.Id, task.WhatId);
        System.assertEquals(opp.OwnerId, task.OwnerId);
        System.assertEquals(closeDate.addDays(7), task.ActivityDate);
        System.assertEquals(TASK_PRIORITY, task.Priority);

        Account updatedAccount = [SELECT Rating FROM Account WHERE Id = :accountId];
        System.assertEquals('Hot', updatedAccount.Rating,
            'Account rating must become Hot');
    }

    @IsTest
    static void testInsertNonWonOpportunityChangesNothing() {
        Id accountId = getWarmAccountId();
        Date closeDate = Date.today().addDays(30);
        Opportunity opp = newOpportunity(accountId, STAGE_PROSPECTING, closeDate);

        Test.startTest();
        insert opp;
        Test.stopTest();

        Opportunity persisted = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(null, persisted.NextStep,
            'NextStep must not be set for a non-won insert');

        System.assertEquals(0, [SELECT COUNT() FROM Task WHERE WhatId = :opp.Id],
            'No task must be created for a non-won insert');

