        Integer dmlRowsAfter = Limits.getDMLRows();

        // One row for the Opportunity insert plus one row for the Task.
        // The already-Hot account must not be updated, so no Account row.
        System.assertEquals(2, dmlRowsAfter - dmlRowsBefore,
