    @IsTest
    static void testBulkInsertUsesSingleQuery() {
        Id accountId = getWarmAccountId();
        Date closeDate = Date.today().addDays(30);
        List<Opportunity> opps = new List<Opportunity>();
        for (Integer i = 0; i < 200; i++) {
            String stage = (i < 100) ? STAGE_CLOSED_WON : STAGE_PROSPECTING;
            opps.add(newOpportunity(accountId, stage, closeDate));
        }

        Test.startTest();
        Integer queriesBefore = Limits.getQueries();
        insert opps;
        Test.stopTest();
        Integer queriesAfter = Limits.getQueries();

        System.assertEquals(1, queriesAfter - queriesBefore,
            'Bulk trigger execution must use at most one SOQL query');

        List<Opportunity> persisted = [SELECT NextStep FROM Opportunity WHERE Id IN :opps];
        Integer wonCount = 0;
        for (Opportunity o : persisted) {
            if (o.NextStep == NEXT_STEP_HANDOVER) {
                wonCount++;
            }
