public class PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names must be provided.');
        }

        Schema.SObjectType sObjectType = null;
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        for (String apiName : globalDescribe.keySet()) {
            if (apiName.equalsIgnoreCase(objectApiName)) {
                sObjectType = globalDescribe.get(apiName);
                break;
            }
        }

        if (sObjectType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objectDescribe = sObjectType.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

        Schema.SObjectField field = null;
        for (String apiName : fieldMap.keySet()) {
            if (apiName.equalsIgnoreCase(fieldApiName)) {
                field = fieldMap.get(apiName);
                break;
            }
        }

        if (field == null) {
            throw new PicklistServiceException('Field does not exist on object: ' + fieldApiName);
        }

        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        if (fieldDescribe.getType() != Schema.DisplayType.Picklist &&
            fieldDescribe.getType() != Schema.DisplayType.MultiPicklist) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist.');
        }

        List<Schema.PicklistEntry> picklistValues = fieldDescribe.getPicklistValues();
        List<Option> options = new List<Option>();

        for (Schema.PicklistEntry entry : picklistValues) {
            if (entry.isActive()) {
                options.add(new Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefaultValue()
                ));
            }
        }

        return options;
    }
}
