public class ShipmentEventHandler {
    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        Set<String> orderNumbers = new Set<String>();
        for (FB_Shipment_Event__e event : events) {
            if (event == null || String.isBlank(event.Order_Number__c)) {
                continue;
            }
            orderNumbers.add(event.Order_Number__c.trim().toUpperCase());
        }

        if (orderNumbers.isEmpty()) {
            return;
        }

        Map<String, FB_Sales_Order__c> ordersByNumber = new Map<String, FB_Sales_Order__c>();
        for (FB_Sales_Order__c order : [
                SELECT Id,
                       Order_Number__c,
                       Status__c
                FROM FB_Sales_Order__c
                WHERE Order_Number__c IN :orderNumbers
            ]) {
            ordersByNumber.put(order.Order_Number__c.trim().toUpperCase(), order);
        }

        Map<String, FB_Sales_Order__c> ordersToUpdate = new Map<String, FB_Sales_Order__c>();
        Date shippedDate = Date.today();

        for (FB_Shipment_Event__e event : events) {
            if (event == null || String.isBlank(event.Order_Number__c)) {
                continue;
            }

            String orderKey = event.Order_Number__c.trim().toUpperCase();
            FB_Sales_Order__c order = ordersByNumber.get(orderKey);

            if (order == null || order.Status__c == 'Cancelled') {
                continue;
            }

            // Repeated events for the same order overwrite the same map entry,
            // so the last event in the list wins.
            FB_Sales_Order__c updateOrder = new FB_Sales_Order__c(Id = order.Id);
            updateOrder.Status__c = 'Shipped';
            updateOrder.Tracking_Number__c = event.Tracking_Number__c;
            updateOrder.Carrier__c = event.Carrier__c;
            updateOrder.Shipped_Date__c = shippedDate;
            ordersToUpdate.put(orderKey, updateOrder);
        }

        if (!ordersToUpdate.isEmpty()) {
            update new List<FB_Sales_Order__c>(ordersToUpdate.values());
        }
    }
}
