public class ErpAccountSyncJob implements Queueable {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = new Set<Id>(accountIds);
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before doing any work so every run is logged,
        // including runs that fail.
        System.enqueueJob(this, new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accounts = [
            SELECT Id
            FROM Account
            WHERE Id IN :accountIds
        ];

        for (Account account : accounts) {
            account.Description = 'Synced to ERP';
        }

        // All-or-nothing save: if any account cannot be saved, an exception is
        // thrown (not caught) and none of the changes are kept.
        Database.update(accounts, true);
    }
}
