public class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = new Set<Id>(accountIds);
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        FB_Job_Log__c log = new FB_Job_Log__c();
        log.Job_Name__c = 'ErpAccountSyncJob';
        log.Attempt__c = attempt;

        Exception exception = context.getException();
        if (exception == null) {
            log.Status__c = 'Success';
        } else {
            log.Status__c = 'Failed';
            String message = exception.getMessage();
            if (message != null && message.length() > 255) {
                message = message.substring(0, 255);
            }
            log.Error__c = message;
        }

        insert log;

        // Retry while below the maximum of three attempts. After the third
        // failed attempt nothing more is enqueued.
        if (exception != null && attempt < 3) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
