public with sharing class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        DateTime cutoff30 = DateTime.now().addDays(-30);
        DateTime cutoff180 = DateTime.now().addDays(-180);

        List<Id> logIds = new List<Id>();
        for (FB_Integration_Log__c log : [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < :cutoff30)
               OR (Level__c = 'ERROR' AND CreatedDate < :cutoff180)
        ]) {
            logIds.add(log.Id);
        }

        if (!logIds.isEmpty()) {
            // DML calls are limited to 10,000 records; chunk to stay within limits.
            Integer chunkSize = 10000;
            for (Integer i = 0; i < logIds.size(); i += chunkSize) {
                Database.delete(
                    logIds.subList(i, Math.min(i + chunkSize, logIds.size())),
                    false
                );
            }
        }
    }

    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }
}
