public with sharing class OpportunityRollupService {
    /**
     * Returns the sum of Amount for each requested Account's won Opportunities
     * whose CloseDate falls in the current calendar year.
     *
     * @param accountIds Set of Account Ids to roll up.
     * @return Map of Account Id -> total won Amount this year (0 if none, never null).
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        Integer currentYear = Date.today().year();
        Date yearStart = Date.newInstance(currentYear, 1, 1);
        Date yearEnd = Date.newInstance(currentYear, 12, 31);

        // Seed every requested account with 0 so missing/qualified-but-null accounts are never null.
        Map<Id, Decimal> rollup = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            rollup.put(accountId, 0);
        }

        // Single aggregate query: sums computed in the database, no Opportunity records loaded.
        for (AggregateResult ar : [
                SELECT AccountId accountId, SUM(Amount) totalAmount
                FROM Opportunity
                WHERE AccountId IN :accountIds
                  AND IsWon = true
                  AND CloseDate >= :yearStart
                  AND CloseDate <= :yearEnd
                GROUP BY AccountId
            ]) {
            Id accountId = (Id) ar.get('accountId');
            Decimal amount = (Decimal) ar.get('totalAmount');
            rollup.put(accountId, amount == null ? 0 : amount);
        }

        return rollup;
    }
}
