public with sharing class Application {

    /**
     * Factory for creating units of work.
     * Configured for Account, Contact, Opportunity and OpportunityContactRole
     * so a single commit can insert new accounts with their contacts and
     * opportunities, plus opportunity contact roles linking them.
     */
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(
            new Schema.SObjectType[] {
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            }
        );

    /**
     * Factory for creating service layer instances.
     */
    public static final fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory();

    /**
     * Factory for creating selector layer instances.
     */
    public static final fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory();

    /**
     * Factory for creating domain layer instances.
     * Wired to the Selector factory so building a domain from a set of record
     * ids queries the records through the registered selector.
     */
    public static final fflib_Application.DomainFactory Domain =
        new fflib_Application.DomainFactory(Selector);

    static {
        // -----------------------------------------------------------------
        // Unit of work relationships
        // -----------------------------------------------------------------
        // Contact belongs to Account.
        Application.UnitOfWork.registerRelationship(
            Contact.SObjectType,
            Contact.AccountId,
            Account.SObjectType
        );

        // Opportunity belongs to Account.
        Application.UnitOfWork.registerRelationship(
            Opportunity.SObjectType,
            Opportunity.AccountId,
            Account.SObjectType
        );

        // OpportunityContactRole belongs to Contact.
        Application.UnitOfWork.registerRelationship(
            OpportunityContactRole.SObjectType,
            OpportunityContactRole.ContactId,
            Contact.SObjectType
        );

        // OpportunityContactRole belongs to Opportunity.
        Application.UnitOfWork.registerRelationship(
            OpportunityContactRole.SObjectType,
            OpportunityContactRole.OpportunityId,
            Opportunity.SObjectType
        );

        // -----------------------------------------------------------------
        // Services
        // -----------------------------------------------------------------
        Application.Service.registerService(
            IAccountsService.class,
            new AccountsServiceImpl()
        );

        // -----------------------------------------------------------------
        // Selectors
        // -----------------------------------------------------------------
        Application.Selector.registerSelector(
            Account.SObjectType,
            new AccountsSelector()
        );

        Application.Selector.registerSelector(
            Contact.SObjectType,
            new ContactsSelector()
        );

        // -----------------------------------------------------------------
        // Domains
        // -----------------------------------------------------------------
        Application.Domain.registerDomain(
            Account.SObjectType,
            Accounts.Constructor.class
        );
    }
}
