public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities((List<Opportunity>) records);
        }
    }

    public override void onAfterInsert() {
        startFulfilment(qualifyingInsertIds());
    }

    public override void onAfterUpdate() {
        startFulfilment(qualifyingUpdateIds());
    }

    private Set<Id> qualifyingInsertIds() {
        Set<Id> opportunityIds = new Set<Id>();
        for (Opportunity opportunity : (List<Opportunity>) records) {
            if (opportunity.StageName == 'Closed Won') {
                opportunityIds.add(opportunity.Id);
            }
        }
        return opportunityIds;
    }

    private Set<Id> qualifyingUpdateIds() {
        Set<Id> opportunityIds = new Set<Id>();
        for (Opportunity opportunity : (List<Opportunity>) records) {
            Opportunity priorOpportunity = (Opportunity) oldMap.get(opportunity.Id);
            if (priorOpportunity != null &&
                priorOpportunity.StageName != 'Closed Won' &&
                opportunity.StageName == 'Closed Won') {
                opportunityIds.add(opportunity.Id);
            }
        }
        return opportunityIds;
    }

    private void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds.isEmpty()) {
            return;
        }
        IOpportunityFulfilmentService fulfilmentService =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        fulfilmentService.startFulfilment(opportunityIds);
    }
}
