        List<SObject> sobjectRecords = new List<SObject>();
        for (Account record : records) {
            sobjectRecords.add(record);
        }
        return (IAccounts) Application.Domain.newInstance(Account.SObjectType, sobjectRecords);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        return (IAccounts) Application.Domain.newInstance(Account.SObjectType, accountIds);
    }

    public class Constructor implements fflib_IDomainFactory {
        public fflib_ISObjects newInstance(List<SObject> records) {
            return new Accounts(records);
        }

        public fflib_ISObjects newInstance(Set<Id> recordIds) {
            fflib_ISObjectSelector selector = Application.Selector.newInstance(Account.SObjectType);
            List<SObject> records = selector.selectById(recordIds);
            return new Accounts(records);
        }
    }

    public override SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public override SObjectType getType() {
        return Account.SObjectType;
    }

    public List<Account> getAccounts() {
        List<Account> accounts = new List<Account>();
        for (SObject record : getSObjects()) {
            accounts.add((Account) record);
        }
        return accounts;
    }

    public IAccounts selectByRating(String rating) {
        List<Account> filtered = new List<Account>();
        for (Account account : getAccounts()) {
            if (account.Rating == rating) {
                filtered.add(account);
            }
        }
        return newInstance(filtered);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account account : getAccounts()) {
            if (account.OwnerId != null) {
                ownerIds.add(account.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account account : getAccounts()) {
            account.Rating = rating;
        }
    }
