public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<sObject> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<sObject> records) {
            return new Opportunities(records);
        }
    }

    public override void onBeforeInsert() {
        validateAmountIsNotNegative();
    }

    public override void onBeforeUpdate() {
        validateAmountIsNotNegative();
        validateAmountNotChangedWhenAlreadyWon();
    }

    private void validateAmountIsNotNegative() {
        for (SObject record : newRecords.values()) {
            Opportunity opp = (Opportunity) record;
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    private void validateAmountNotChangedWhenAlreadyWon() {
        for (SObject record : newRecords.values()) {
            Opportunity newOpp = (Opportunity) record;
            Opportunity oldOpp = (Opportunity) existingRecords.get(newOpp.Id);
            if (oldOpp == null) {
                continue;
            }
            if (oldOpp.StageName == 'Closed Won' && newOpp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', newOpp, Opportunity.Amount);
            }
        }
    }
}
