public inherited sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        fflib_SObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        IOpportunitiesSelector selector = OpportunitiesSelector.newInstance();
        List<Opportunity> opportunities = selector.selectById(opportunityIds);

        Integer closedCount = 0;

        for (Opportunity opp : opportunities) {
            // Skip opportunities that are already Closed Won
            if (opp.StageName == 'Closed Won') {
                continue;
            }

            Opportunity oppToUpdate = new Opportunity(Id = opp.Id);
            oppToUpdate.StageName = 'Closed Won';
            oppToUpdate.CloseDate = Date.today();
            uow.registerDirty(oppToUpdate);

            Deal_Won__e dealWon = new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c = opp.Amount
            );
            uow.registerNew(dealWon);

            closedCount++;
        }

        if (closedCount > 0) {
            // Commit once. If this fails the exception propagates and the
            // transaction rolls back, so no Deal_Won__e events are published.
            uow.commitWork();
        }

        return closedCount;
    }
}
