public class PipelineSummary {

    /**
     * Returns total Amount for the four open pipeline stages, grouped by StageName,
     * for Opportunities whose CloseDate falls inclusively between fromDate and toDate.
     *
     * Implementation note: per the request, this runs one simple SUM(Amount) aggregate
     * query per stage (four queries total). A single GROUP BY query would be more
     * bulk-friendly, but four isolated queries keep the logic explicit and easy to
     * audit for this fixed, small stage list.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        List<String> stages = new List<String>{
            'Prospecting',
            'Qualification',
            'Proposal/Price Quote',
            'Negotiation/Review'
        };

        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : stages) {
            totals.put(stage, 0);
        }

        for (String stage : stages) {
            List<AggregateResult> results = [
                SELECT SUM(Amount) stageTotal
                FROM Opportunity
                WHERE StageName = :stage
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ];

            if (!results.isEmpty() && results[0].get('stageTotal') != null) {
                totals.put(stage, (Decimal)results[0].get('stageTotal'));
            }
        }

        return totals;
    }
}
