public with sharing class FollowUpTaskService {
    /**
     * Creates a follow-up Task for each Opportunity.
     *
     * Tasks are inserted one at a time inside try/catch so that a validation-rule
     * rejection on one Task does not prevent the others from being created.
     *
     * @param opportunityIds Ids of the Opportunities to follow up on.
     * @return Ids of Opportunities whose Task could not be created (empty when all succeed).
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // De-duplicate and drop nulls before querying.
        Set<Id> ids = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                ids.add(opportunityId);
            }
        }

        if (ids.isEmpty()) {
            return failedOpportunityIds;
        }

        Map<Id, Opportunity> opportunityMap = new Map<Id, Opportunity>([
            SELECT Id, OwnerId, Name
            FROM Opportunity
            WHERE Id IN :ids
        ]);

        Date followUpDate = Date.today().addDays(7);

        // NOTE: This follows the requested straightforward pattern of one insert per Task.
        // Salesforce enforces a maximum of 150 DML statements per transaction, so a single
        // call with more than ~150 Opportunities can hit that governor limit. If reviews
        // regularly exceed 150 records, consider Database.insert(tasks, false) with error
        // mapping, but that would change the one-at-a-time behaviour asked for here.
        for (Opportunity opportunity : opportunityMap.values()) {
            Task task = new Task(
                WhatId       = opportunity.Id,
                OwnerId      = opportunity.OwnerId,
                Subject      = 'Follow up: ' + opportunity.Name,
                ActivityDate = followUpDate,
                Status       = 'Not Started',
                Priority     = 'Normal'
            );

            try {
                insert task;
            } catch (Exception ex) {
                failedOpportunityIds.add(opportunity.Id);
            }
        }

        return failedOpportunityIds;
    }
}
