/**
 * OpportunityTrigger
 *
 * Recalculates the parent Account's Rating asynchronously when an Opportunity is
 * inserted, or when its StageName or Amount changes.
 *
 * NOTE (deviation from the request): Instead of calling @future once per Opportunity,
 * this trigger collects unique AccountIds and makes a single @future call per
 * transaction. One @future per Opportunity in a 200-record CPQ batch would generate
 * 200 asynchronous calls, risking org-wide asynchronous Apex limits, causing
 * redundant recalculations for the same Account, and creating last-write-wins race
 * conditions. Batching unique AccountIds is bulk-safe and follows current best
 * practice.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {
    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {
        Boolean recalculate = false;

        if (Trigger.isInsert) {
            recalculate = true;
        } else if (Trigger.isUpdate) {
            Opportunity prior = Trigger.oldMap.get(opp.Id);
            if (prior.StageName != opp.StageName || prior.Amount != opp.Amount) {
                recalculate = true;
            }
        }

        if (recalculate && opp.AccountId != null) {
            accountIds.add(opp.AccountId);
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
