/**
 * AccountRatingService
 *
 * Recalculates Account.Rating from the open Opportunity pipeline:
 *   Hot  - at least one open Opportunity with Amount >= 100,000
 *   Warm - open Opportunities exist, but none >= 100,000
 *   Cold - no open Opportunities
 *
 * NOTE (deviation from the request): The @future method accepts a Set<Id> rather than
 * a single Id so the trigger can batch all affected Accounts into one asynchronous
 * call. This avoids hitting asynchronous Apex limits, eliminates duplicate
 * recalculations for the same Account, and prevents race conditions when CPQ
 * inserts or updates Opportunities in batches of 200.
 */
public class AccountRatingService {
    private static final Decimal LARGE_OPPORTUNITY_AMOUNT = 100000;

    @future
    public static void recalculate(Set<Id> accountIds) {
        accountIds.remove(null);

        if (accountIds.isEmpty()) {
            return;
        }

        // Aggregate open Opportunities by Account. IsClosed = false identifies open.
        Map<Id, AggregateResult> openOppByAccount = new Map<Id, AggregateResult>();
        for (AggregateResult ar : [
            SELECT AccountId accountId, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE IsClosed = false
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            openOppByAccount.put((Id) ar.get('accountId'), ar);
        }

        Map<Id, Account> accounts = new Map<Id, Account>([
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();

        for (Id accountId : accountIds) {
            AggregateResult ar = openOppByAccount.get(accountId);
            String rating;

            if (ar == null) {
                rating = 'Cold';
            } else {
                Decimal maxAmount = (Decimal) ar.get('maxAmount');
                if (maxAmount != null && maxAmount >= LARGE_OPPORTUNITY_AMOUNT) {
                    rating = 'Hot';
                } else {
                    rating = 'Warm';
                }
            }

            Account acc = accounts.get(accountId);
            if (acc != null && acc.Rating != rating) {
                acc.Rating = rating;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
