public with sharing class LeadContactMatcher {
    /**
     * Matches each Lead to a Contact by email address.
     *
     * @param leads     the leads to match; the result list preserves this order
     * @param contacts  the contacts to search
     * @return a List<Id> the same size as leads. Each element is the Id of the first
     *         contact in contacts whose email matches the lead's email, or null if no
     *         match exists or either email is blank. Emails are compared case-insensitively
     *         after trimming leading/trailing whitespace. No records are queried or modified.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> matchedIds = new List<Id>(leads == null ? 0 : leads.size());

        if (leads == null) {
            return matchedIds;
        }

        for (Lead lead : leads) {
            Id contactId = null;
            String normalizedLeadEmail = normalizeEmail(lead.Email);

            if (normalizedLeadEmail != null && contacts != null) {
                for (Contact contact : contacts) {
                    String normalizedContactEmail = normalizeEmail(contact.Email);
                    if (normalizedContactEmail != null &&
                        normalizedLeadEmail.equalsIgnoreCase(normalizedContactEmail)) {
                        contactId = contact.Id;
                        break; // first match in contacts order wins
                    }
                }
            }

            matchedIds.add(contactId);
        }

        return matchedIds;
    }

    private static String normalizeEmail(String email) {
        return String.isBlank(email) ? null : email.trim();
    }
}
