```apex
// CaseTrigger.trigger
//
// Design notes:
// - After-update only. No SOQL or DML runs in the trigger; the survey work is asynchronous.
// - One Queueable job is enqueued per newly closed case, so one job failure cannot affect other cases.
// - Each job re-reads the case at run time and creates the task only when the case is still closed
//   and still has a contact.
//
// Governor note: System.enqueueJob is limited to 50 queueable jobs per transaction. If a single
// transaction can close more than 50 cases (for example, 200-record Bulk API batches), route these
// enqueues through a chunking dispatcher that enqueues at most 50 jobs per Queueable transaction.
// The per-case CaseSurveyJob below remains the failure boundary for each case.
trigger CaseTrigger on Case (after update) {
    for (Case closedCase : Trigger.new) {
        Case priorCase = Trigger.oldMap.get(closedCase.Id);

        if (priorCase == null) {
            continue;
        }

        // IsClosed is formula-driven; act only on a real not-closed -> closed transition.
        if (!closedCase.IsClosed || priorCase.IsClosed) {
            continue;
        }

        // Cases without a contact get no survey task.
        if (closedCase.ContactId == null) {
            continue;
        }

        System.enqueueJob(new CaseSurveyJob(closedCase.Id));
    }
}
