```apex
public class RenewalReminderService {

    /**
     * Sends a renewal reminder email to the owner of each opportunity.
     *
     * Implementation notes:
     * - Messaging.sendEmail is invoked once per opportunity, inside the loop, exactly as
     *   requested. This isolates failures: if one email is rejected or throws, the rest
     *   are still attempted.
     * - Calling sendEmail in a loop is generally a bad idea for large batches because it
     *   is slower and consumes more Apex email invocations than passing a list of messages
     *   to a single sendEmail call. It also makes it easier to hit transaction or daily
     *   email limits. For high volume, prefer batching messages into fewer sendEmail calls
     *   or moving the work to a Queueable/batch job.
     * - Emails sent to Users via setTargetObjectId do not count against the org's daily
     *   external email limit, but they are still subject to Apex governor limits and the
     *   org's overall email sending capacity.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Deduplicate in case the caller passes the same Id more than once.
        Set<Id> uniqueIds = new Set<Id>(opportunityIds);

        // One bulk SOQL query. Owner.Email is fetched here so we do not need SOQL inside
        // the loop to decide whether an owner can receive email.
        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId, Owner.Email
            FROM Opportunity
            WHERE Id IN :uniqueIds
        ];

        Integer sentSuccessfully = 0;

        for (Opportunity opp : opportunities) {
            // An Opportunity can be owned by a User or a Queue. setTargetObjectId only
            // accepts User, Contact, or Lead Ids.
            if (opp.OwnerId == null || opp.OwnerId.getSObjectType() != User.sObjectType) {
                continue;
            }

            // Do not attempt to email a User who has no email address configured.
            if (opp.Owner == null || String.isBlank(opp.Owner.Email)) {
                continue;
            }

            // The plain-text body must mention the close date. Skip records with no
            // close date because the body cannot be completed meaningfully.
            if (opp.CloseDate == null) {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody(
                'Renewal reminder for opportunity "' + opp.Name + '". ' +
                'The close date is ' + opp.CloseDate.format() + '.'
            );

            try {
                Messaging.SendEmailResult[] results = Messaging.sendEmail(
                    new Messaging.SingleEmailMessage[] { email }
                );

                if (results != null && !results.isEmpty() && results[0].isSuccess()) {
                    sentSuccessfully++;
                }
            } catch (Exception ex) {
                // An individual email failure must not stop the remaining reminders.
                // Continue to the next opportunity.
            }
        }

        return sentSuccessfully;
    }
}
