public with sharing class AccountCountrySync {
    private AccountCountrySync() {}

    /**
     * Cascade BillingCountry changes to Contact.MailingCountry.
     *
     * Deliberate change from loading all contacts once:
     *   [SELECT Id, AccountId, MailingCountry FROM Contact]
     *   without a WHERE clause is non-selective against ~2.3 million contacts and
     *   throws QueryException. Contact.AccountId is indexed, so this handler runs
     *   one selective query for only the accounts whose BillingCountry changed in
     *   the current trigger batch. There are no queries inside loops, and contact
     *   DML is also outside loops.
     */
    public static void onAfterUpdate(Map<Id, Account> newMap, Map<Id, Account> oldMap) {
        if (newMap == null || oldMap == null) {
            return;
        }

        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> oldBillingCountryByAccount = new Map<Id, String>();
        Map<Id, String> newBillingCountryByAccount = new Map<Id, String>();

        for (Id accountId : newMap.keySet()) {
            Account newAccount = newMap.get(accountId);
            Account oldAccount = oldMap.get(accountId);

            if (newAccount == null || oldAccount == null) {
                continue;
            }

            if (newAccount.BillingCountry != oldAccount.BillingCountry) {
                changedAccountIds.add(accountId);
                oldBillingCountryByAccount.put(accountId, oldAccount.BillingCountry);
                newBillingCountryByAccount.put(accountId, newAccount.BillingCountry);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        // One query. No loop queries.
        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ];

        Map<Id, List<Contact>> contactsByAccountId = new Map<Id, List<Contact>>();
        for (Contact contact : contacts) {
            List<Contact> accountContacts = contactsByAccountId.get(contact.AccountId);
            if (accountContacts == null) {
                accountContacts = new List<Contact>();
                contactsByAccountId.put(contact.AccountId, accountContacts);
            }
            accountContacts.add(contact);
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Id accountId : changedAccountIds) {
            String oldBillingCountry = oldBillingCountryByAccount.get(accountId);
            String newBillingCountry = newBillingCountryByAccount.get(accountId);
            List<Contact> accountContacts = contactsByAccountId.get(accountId);

            if (accountContacts == null) {
                continue;
            }

            for (Contact contact : accountContacts) {
                String mailingCountry = contact.MailingCountry;
                Boolean mailingIsBlank = String.isBlank(mailingCountry);

                Boolean matchesOldBillingCountry = !mailingIsBlank
                    && oldBillingCountry != null
                    && !String.isBlank(oldBillingCountry)
                    && mailingCountry.equals(oldBillingCountry);

                if (!mailingIsBlank && !matchesOldBillingCountry) {
                    continue;
                }

                Boolean newBillingIsBlank = String.isBlank(newBillingCountry);
                Boolean alreadyEqualsNew = mailingIsBlank
                    ? newBillingIsBlank
                    : mailingCountry.equals(newBillingCountry);

                if (alreadyEqualsNew) {
                    continue;
                }

                contactsToUpdate.add(new Contact(
                    Id = contact.Id,
                    MailingCountry = newBillingCountry
                ));
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
