import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];
    showError = false;

    handleClick(event) {
        const action = event.currentTarget.dataset.action;

        if (action === 'reset') {
            this._handleReset();
        } else if (action === 'submit') {
            this._handleSubmit();
        }
    }

    _handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach((editor) => editor.reset());
    }

    _handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');

        // Validate every editor so all invalid lines show their errors at once.
        const validityResults = editors.map((editor) => editor.validate());
        const allValid = validityResults.every((isValid) => isValid);

        if (allValid) {
            this.showError = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    bubbles: true,
                    composed: true,
                    detail: { lines }
                })
            );
        } else {
            this.showError = true;
        }
    }
}
