import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60 * 1000;

export default class QueueMonitor extends LightningElement {
    @track waiting;
    @track longestWaitMinutes;
    @track error;
    @track statsLoaded = false;

    intervalId = null;
    inFlight = false;

    connectedCallback() {
        this.loadStats();
        this.startPolling();
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    handleVisibilityChange = () => {
        if (document.visibilityState !== 'visible') {
            return;
        }
        this.stopPolling();
        this.loadStats();
        this.startPolling();
    }

    startPolling() {
        this.intervalId = setInterval(() => {
            this.refreshIfAllowed();
        }, POLL_INTERVAL_MS);
    }

    stopPolling() {
        if (this.intervalId !== null) {
            clearInterval(this.intervalId);
            this.intervalId = null;
        }
    }

    refreshIfAllowed() {
        if (document.visibilityState === 'hidden') {
            return;
        }
        if (this.inFlight) {
            return;
        }
        this.loadStats();
    }

    loadStats() {
        if (this.inFlight) {
            return;
        }

        this.inFlight = true;

        getQueueStats()
            .then((result) => {
                this.statsLoaded = true;
                this.error = undefined;
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
            })
            .catch((error) => {
                this.error = error.body?.message ?? String(error);
            })
            .finally(() => {
                this.inFlight = false;
            });
    }
}
