import { LightningElement, api, track } from 'lwc';

const MOVE_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End']);
const SELECT_KEYS = new Set(['Enter', ' ']);
const HANDLED_KEYS = new Set([...MOVE_KEYS, ...SELECT_KEYS]);

export default class StatusListbox extends LightningElement {
  @api label;
  _options = [];
  _value;

  @track activeIndex = 0;
  _uid;

  constructor() {
    super();
    this._uid = `statusListbox-${Math.random().toString(36).slice(2, 9)}`;
  }

  connectedCallback() {
    this._syncActiveToValue();
  }

  @api
  get options() {
    return this._options;
  }

  set options(list) {
    this._options = list ?? [];
    this._syncActiveToValue();
  }

  @api
  get value() {
    return this._value;
  }

  set value(val) {
    this._value = val;
    this._syncActiveToValue();
  }

  _syncActiveToValue() {
    const opts = this._options;
    const idx = opts.findIndex((option) => option.value === this._value);
    this.activeIndex = idx !== -1 ? idx : (opts.length ? 0 : -1);
  }

  get activeOptionId() {
    const opts = this._options;
    if (!opts.length || this.activeIndex < 0 || this.activeIndex >= opts.length) {
      return undefined;
    }
    return `${this._uid}-option-${this.activeIndex}`;
  }

  getOptionId(index) {
    return `${this._uid}-option-${index}`;
  }

  handleKeydown(event) {
    const { key } = event;
    if (!HANDLED_KEYS.has(key)) {
      return;
    }
    event.preventDefault();

    const opts = this._options;
    if (!opts.length) {
      return;
    }

    if (key === 'ArrowDown') {
      this.activeIndex = Math.min(this.activeIndex + 1, opts.length - 1);
    } else if (key === 'ArrowUp') {
      this.activeIndex = Math.max(this.activeIndex - 1, 0);
    } else if (key === 'Home') {
      this.activeIndex = 0;
    } else if (key === 'End') {
      this.activeIndex = opts.length - 1;
    } else {
      this._selectActive();
    }
  }

  _selectActive() {
    const opts = this._options;
    if (this.activeIndex < 0 || this.activeIndex >= opts.length) {
      return;
    }
    const option = opts[this.activeIndex];
    if (option.value === this.value) {
      return;
    }
    this.value = option.value;
    this.dispatchEvent(
      new CustomEvent('change', {
        detail: { value: option.value },
        bubbles: true,
        composed: true
      })
    );
  }

  handleOptionClick(event) {
    const index = Number(event.currentTarget.dataset.index);
    const opts = this._options;
    const option = opts[index];
    if (!option) {
      return;
    }
    this.activeIndex = index;
    if (option.value === this.value) {
      return;
    }
    this.value = option.value;
    this.activeIndex = index;
    this.dispatchEvent(
      new CustomEvent('change', {
        detail: { value: option.value },
        bubbles: true,
        composed: true
      })
    );
  }
}
