import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;
    @api newLabel = '';

    _tasks = [];
    items = [];
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        const copy = Array.isArray(value)
            ? value.map((task) => ({
                  id: task.id,
                  label: task.label,
                  done: Boolean(task.done)
              }))
            : [];
        this._tasks = copy;
        this.items = copy.map((task) => ({ ...task }));
    }

    get displayHeading() {
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = String(this.newLabel).trim();
        if (!label) {
            return;
        }
        const task = { id: `new-${this.nextId++}`, label, done: false };
        this.items = [...this.items, task];
        this.newLabel = '';
        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        const task = this.items.find((t) => t.id === id);
        if (!task) {
            return;
        }
        this.items = this.items.map((t) =>
            t.id === id ? { ...t, done: !t.done } : t
        );
    }
}
