public with sharing class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Query 1: contacts and their current primary affiliation lookup
        Map<Id, Contact> contactMap = new Map<Id, Contact>(
            [SELECT Id, npsp__Primary_Affiliation__c
             FROM Contact
             WHERE Id IN :contactIds]
        );

        // Query 2: existing affiliations for these contacts
        List<npe5__Affiliation__c> existingAffiliations = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c,
                   npe5__Status__c, npe5__Primary__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
        ];

        // Group affiliations by contact for in-memory lookup
        Map<Id, List<npe5__Affiliation__c>> affByContact = new Map<Id, List<npe5__Affiliation__c>>();
        for (npe5__Affiliation__c aff : existingAffiliations) {
            if (!affByContact.containsKey(aff.npe5__Contact__c)) {
                affByContact.put(aff.npe5__Contact__c, new List<npe5__Affiliation__c>());
            }
            affByContact.get(aff.npe5__Contact__c).add(aff);
        }

        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();
        Date today = Date.today();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }

            Contact c = contactMap.get(contactId);
            if (c == null) {
                continue;
            }

            // If the contact's primary affiliation lookup already points to this org, do nothing.
            if (c.npsp__Primary_Affiliation__c == orgId) {
                continue;
            }

            List<npe5__Affiliation__c> affs = affByContact.get(contactId);
            Boolean alreadyPrimaryToOrg = false;
            Id currentPrimaryAffIdToOtherOrg = null;

            if (affs != null) {
                for (npe5__Affiliation__c aff : affs) {
                    if (aff.npe5__Primary__c && aff.npe5__Status__c == 'Current') {
                        if (aff.npe5__Organization__c == orgId) {
                            alreadyPrimaryToOrg = true;
                        } else {
                            currentPrimaryAffIdToOtherOrg = aff.Id;
                        }
                    }
                }
            }

            // Avoid duplicate primary affiliation to the same organization.
            if (alreadyPrimaryToOrg) {
                continue;
            }

            // End-date the previous primary employer as Former, non-primary.
            if (currentPrimaryAffIdToOtherOrg != null) {
                affiliationsToUpdate.add(new npe5__Affiliation__c(
                    Id = currentPrimaryAffIdToOtherOrg,
                    npe5__Status__c = 'Former',
                    npe5__Primary__c = false,
                    npe5__EndDate__c = today
                ));
            }

            // Create the new Current, primary affiliation.
            affiliationsToInsert.add(new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = orgId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = today
            ));
        }

        // DML 1: end-date previous primary affiliations
        if (!affiliationsToUpdate.isEmpty()) {
            update affiliationsToUpdate;
        }

        // DML 2: insert new primary affiliations
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }
}
