public with sharing class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String STATUS_IMPORTED = 'Imported';
    private static final String STATUS_PENDING = 'Pending';
    private static final String DONOR_CONTACT1 = 'Contact1';

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // Stage one NPSP Data Import record per gift, preserving input order.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            staged.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c     = gift.firstName,
                npsp__Contact1_Lastname__c      = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c        = gift.amount,
                npsp__Donation_Date__c          = gift.giftDate,
                npsp__Donation_Donor__c         = DONOR_CONTACT1,
                npsp__Status__c                 = STATUS_PENDING
            ));
        }

        // The staged records remain in the org as the import audit trail.
        insert staged;

        // The org's Data Import settings (hierarchy custom setting, org defaults).
        npsp__Data_Import_Settings__c importSettings =
            npsp__Data_Import_Settings__c.getOrgDefaults();
        Id importSettingsId = (importSettings == null) ? null : importSettings.Id;

        // Process synchronously in this transaction using NPSP's Apex data import
        // API and the org's import settings. NPSP applies contact matching,
        // household creation and donation processing rules, then writes the outcome
        // back to each staged record. Row-level rejections are recorded per record
        // and do not stop the other rows.
        try {
            npsp.DataImport.importRecords(staged, importSettingsId);
        } catch (Exception e) {
            // The import engine itself failed; report every row as failed while
            // still returning one result per gift in input order.
            return buildResults(staged, null, e.getMessage());
        }

        // Read the processed records so results reflect what NPSP wrote to the DB.
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>(
            [SELECT npsp__Status__c,
                    npsp__Contact1Imported__c,
                    npsp__DonationImported__c,
                    npsp__FailureInformation__c
             FROM npsp__DataImport__c
             WHERE Id IN :staged]
        );

        return buildResults(staged, processedById, null);
    }

    private static List<ImportResult> buildResults(List<npsp__DataImport__c> staged,
            Map<Id, npsp__DataImport__c> processedById,
            String systemicErrorMessage) {
        List<ImportResult> results = new List<ImportResult>();
        for (npsp__DataImport__c di : staged) {
            ImportResult r = new ImportResult();
            npsp__DataImport__c processed =
                (processedById == null) ? null : processedById.get(di.Id);

            if (systemicErrorMessage != null) {
                r.success = false;
                r.errorMessage = systemicErrorMessage;
                results.add(r);
                continue;
            }

            String status = (processed != null) ? processed.npsp__Status__c : di.npsp__Status__c;
            r.success = STATUS_IMPORTED.equalsIgnoreCase(status);
            r.contactId = (processed != null) ? processed.npsp__Contact1Imported__c
                                              : di.npsp__Contact1Imported__c;
            r.opportunityId = (processed != null) ? processed.npsp__DonationImported__c
                                                  : di.npsp__DonationImported__c;
            if (!r.success) {
                r.errorMessage = (processed != null) ? processed.npsp__FailureInformation__c
                                                     : di.npsp__FailureInformation__c;
            }
            results.add(r);
        }
        return results;
    }
}
