public with sharing class GauAllocationService {
    public class AllocationException extends Exception {}

    /**
     * Replace all GAU allocations for an opportunity with one allocation per
     * entry in percentByGauId.
     *
     * Keys are npsp__General_Accounting_Unit__c Ids; values are percentages
     * where 60 means 60%. A total below 100% is allowed (the remainder stays
     * unallocated).
     *
     * Each allocation stores both the calculated Amount (based on the current
     * opportunity amount) and the Percent. Keeping the Percent means the
     * allocation stays proportional if the opportunity amount is later changed
     * (e.g. $1,000 at 60/40 corrected to $2,000 becomes $1,200/$800) without
     * further code in this service.
     *
     * All validation runs before any data is changed.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation percentage is required.');
        }

        Opportunity opp = [
            SELECT Amount
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opp == null) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }
        Decimal giftAmount = opp.Amount == null ? 0 : opp.Amount;

        Decimal totalPercent = 0;
        Set<Id> gauIds = new Set<Id>();

        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id in the allocation map is null.');
            }

            gauIds.add(gauId);

            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'GAU percentage must be greater than 0 for GAU: ' + gauId
                );
            }

            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'GAU percentages total more than 100% (' + totalPercent + '%).'
            );
        }

        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
            ]
        );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau == null || !gau.npsp__Active__c) {
                throw new AllocationException(
                    'GAU is inactive or does not exist: ' + gauId
                );
            }
        }

        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);

            npsp__Allocation__c allocation = new npsp__Allocation__c();
            allocation.npsp__Opportunity__c = opportunityId;
            allocation.npsp__General_Accounting_Unit__c = gauId;
            allocation.npsp__Percent__c = pct;
            allocation.npsp__Amount__c = giftAmount * pct / 100;

            allocations.add(allocation);
        }

        // Replace: every change above is in-memory only; no data has been
        // modified yet. Delete then insert in the same transaction so the
        // replace is atomic.
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        delete existing;

        insert allocations;
        return allocations;
    }
}
