public with sharing class HouseholdService {

    /**
     * Creates a single NPSP Household Account and registers every contact under it.
     *
     * The first contact in the list becomes the household's primary contact
     * (Account.npe01__One2OneContact__c). The Account.Name is intentionally left
     * unset so NPSP automatic household naming and greeting generation own it.
     *
     * All work is all-or-nothing: if any DML fails, the transaction is rolled back
     * so no empty or extra household account is left behind.
     *
     * @param members new contacts (no Id, no AccountId) to register as one household
     * @return the Id of the new Household Account
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        Id householdRecordTypeId = selectHouseholdRecordTypeId();

        Savepoint savepoint = Database.setSavepoint();
        try {
            // NPSP names the household and generates greetings; do not set Name.
            Account household = new Account(RecordTypeId = householdRecordTypeId);
            insert household;

            // Attach every contact to the new household.
            for (Contact member : members) {
                member.AccountId = household.Id;
            }
            insert members;

            // First contact is the household's primary (one-to-one) contact.
            household.npe01__One2OneContact__c = members[0].Id;
            update household;

            return household.Id;
        } catch (Exception e) {
            Database.rollback(savepoint);
            throw e;
        }
    }

    private static Id selectHouseholdRecordTypeId() {
        List<RecordType> recordTypes = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Account'
              AND DeveloperName = 'HH_Account'
            LIMIT 1
        ];

        if (recordTypes.isEmpty()) {
            throw new IllegalStateException(
                'Account record type with DeveloperName HH_Account was not found.'
            );
        }

        return recordTypes[0].Id;
    }
}
