public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    /**
     * Replace an opportunity's unpaid, not-written-off payments with a monthly
     * installment schedule. Paid and written-off payments are left untouched.
     *
     * @param opportunityId      the Opportunity to re-schedule
     * @param numberOfPayments   how many installments to create (must be >= 1)
     * @param firstPaymentDate   date of the first installment; each subsequent one
     *                           is one month later
     * @return the newly inserted payments, in schedule order
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // Validate before touching any data.
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be 1 or greater.');
        }

        List<Opportunity> opps = [
            SELECT Id, Amount, IsClosed,
                (
                    SELECT Id, npe01__Paid__c, npe01__Written_Off__c, npe01__Payment_Amount__c
                    FROM npe01__OppPayment__r
                )
            FROM Opportunity
            WHERE Id = :opportunityId
        ];

        if (opps.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found.');
        }

        Opportunity opp = opps[0];

        if (opp.IsClosed) {
            throw new PaymentPlanException('Cannot schedule installments on a closed opportunity.');
        }

        // Outstanding amount excludes paid and written-off payments.
        Decimal paidTotal = 0;
        for (npe01__OppPayment__c p : opp.npe01__OppPayment__r) {
            if (p.npe01__Paid__c || p.npe01__Written_Off__c) {
                paidTotal += (p.npe01__Payment_Amount__c == null ? 0 : p.npe01__Payment_Amount__c);
            }
        }

        Decimal outstanding = (opp.Amount == null ? 0 : opp.Amount) - paidTotal;

        if (outstanding == null || outstanding <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero.');
        }

        // Work in whole cents so rounding is exact and the final payment absorbs
        // every remaining cent.
        Long totalCents = (outstanding * 100).setScale(0, RoundingMode.DOWN).longValue();
        Long baseCents = totalCents / numberOfPayments;
        Long remainderCents = totalCents - (baseCents * numberOfPayments);

        Decimal baseAmount = (Decimal.valueOf(baseCents) / 100).setScale(2, RoundingMode.DOWN);
        Decimal lastAmount = (Decimal.valueOf(baseCents + remainderCents) / 100).setScale(2, RoundingMode.DOWN);

        // Delete only unpaid, not-written-off payments.
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c p : opp.npe01__OppPayment__r) {
            if (!p.npe01__Paid__c && !p.npe01__Written_Off__c) {
                toDelete.add(p);
            }
        }
        delete toDelete;

        // Insert the new unpaid installments in schedule order.
        List<npe01__OppPayment__c> toInsert = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c p = new npe01__OppPayment__c();
            p.npe01__Opportunity__c = opportunityId;
            p.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            p.npe01__Payment_Date__c = null;
            p.npe01__Paid__c = false;
            p.npe01__Written_Off__c = false;
            p.npe01__Payment_Amount__c = (i == numberOfPayments - 1) ? lastAmount : baseAmount;
            toInsert.add(p);
        }

        insert toInsert;
        return toInsert;
    }
}
