public with sharing class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact ID cannot be null.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date cannot be null.');
        }

        Contact contact = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contact == null || contact.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact does not exist or is not associated with a household account.'
            );
        }

        Opportunity opp = new Opportunity(
            Name = String.format(
                '{0} {1} Donation {2}',
                new List<String>{
                    contact.FirstName == null ? '' : contact.FirstName,
                    contact.LastName == null ? '' : contact.LastName,
                    giftDate.format('yyyy-MM-dd')
                }
            ),
            AccountId = contact.AccountId,
            npsp__Primary_Contact__c = contactId,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            Amount = amount
        );
        insert opp;

        List<ContactRole> contactRoles = new List<ContactRole>();
        contactRoles.add(new ContactRole(
            ContactId = contactId,
            OpportunityId = opp.Id,
            Role = 'Donor',
            IsPrimary = true
        ));

        for (Contact householdMember : [
            SELECT Id
            FROM Contact
            WHERE AccountId = contact.AccountId
              AND Id != :contactId
        ]) {
            contactRoles.add(new ContactRole(
                ContactId = householdMember.Id,
                OpportunityId = opp.Id,
                Role = 'Household Member',
                IsPrimary = false
            ));
        }

        if (!contactRoles.isEmpty()) {
            insert contactRoles;
        }

        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        insert payment;

        return opp.Id;
    }
}
