public class FamilyService {
    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * Links children to parents as NPSP Relationships.
     *
     * For each (childId -> parentId) pair, creates one npe4__Relationship__c where:
     *   npe4__Contact__c        = childId
     *   npe4__RelatedContact__c = parentId
     *   npe4__Type__c           = 'Parent'
     *   npe4__Status__c         = 'Current'
     *
     * Because this org uses NPSP's default "List Setting" reciprocal method, NPSP automatically
     * creates the reciprocal relationship (parent -> child) using the Relationship Lookup for
     * "Parent" (Male: Son, Female: Daughter, Neutral: Child). We therefore only ever write the
     * child -> parent record; the parent then sees the child as Son, Daughter or Child according
     * to the child's gender via NPSP's reciprocal lookup.
     *
     * Pairs that already have a relationship in either direction are skipped, so the import is
     * safe to re-run. Null or empty input does nothing.
     *
     * Bulk safety: regardless of map size, this issues at most one SOQL query and one DML
     * statement (zero when there is nothing to do).
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> childIds = parentIdByChildId.keySet();
        Set<Id> allContactIds = new Set<Id>(childIds);
        allContactIds.addAll(parentIdByChildId.values());

        // One SOQL: surface any existing relationship between any two of the involved contacts.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c existing : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM npe4__Relationship__c
                WHERE npe4__Contact__c IN :allContactIds
                  AND npe4__RelatedContact__c IN :allContactIds
            ]) {
            existingPairKeys.add(pairKey(existing.npe4__Contact__c, existing.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toCreate = new List<npe4__Relationship__c>();
        for (Map.Entry<Id, Id> entry : parentIdByChildId.entrySet()) {
            Id childId = entry.getKey();
            Id parentId = entry.getValue();

            if (childId == null || parentId == null) {
                continue;
            }

            // Skip if a relationship already exists between these two contacts in either direction.
            if (existingPairKeys.contains(pairKey(childId, parentId))) {
                continue;
            }

            toCreate.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = TYPE_PARENT,
                npe4__Status__c = STATUS_CURRENT
            ));
        }

        if (!toCreate.isEmpty()) {
            // One DML. NPSP's reciprocal trigger creates the matching parent -> child record.
            insert toCreate;
        }
    }

    /**
     * Direction-independent key for a pair of contact ids, so an existing relationship is found
     * regardless of which contact occupies npe4__Contact__c versus npe4__RelatedContact__c.
     */
    private static String pairKey(Id a, Id b) {
        String first = String.valueOf(a);
        String second = String.valueOf(b);
        return (first.compareTo(second) <= 0) ? (first + '|' + second) : (second + '|' + first);
    }
}
