public with sharing class AccountOwnershipService {
    /**
     * Reassigns the given Accounts and their Contacts to a new owner.
     *
     * Account trigger automation is bypassed for the duration of the ownership
     * change; Contact automation runs normally. Account automation is restored
     * (bypass cleared) whether the method succeeds or throws.
     *
     * @param accountIds   Accounts to reassign (up to 200).
     * @param newOwnerId   New owner User Id.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        // Bypass all Account trigger actions for this transaction.
        TriggerBase.bypass(Account.sObjectType);

        try {
            // 1 SOQL: gather all Contacts on the Accounts being reassigned.
            List<Contact> contacts = [
                SELECT Id, OwnerId
                FROM Contact
                WHERE AccountId IN :accountIds
            ];

            List<Contact> contactsToUpdate = new List<Contact>();
            for (Contact c : contacts) {
                if (c.OwnerId != newOwnerId) {
                    c.OwnerId = newOwnerId;
                    contactsToUpdate.add(c);
                }
            }

            // Build Account updates without a second SOQL query.
            List<Account> accountsToUpdate = new List<Account>(accountIds.size());
            for (Id accountId : accountIds) {
                accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }

            // All-or-none DML; failures propagate to the caller unchanged.
            Database.update(accountsToUpdate, true);

            if (!contactsToUpdate.isEmpty()) {
                Database.update(contactsToUpdate, true);
            }
        } finally {
            // Restore normal Account automation for the remainder of the transaction.
            TriggerBase.clearBypass(Account.sObjectType);
        }
    }
}
