@IsTest
public with sharing class TA_Opportunity_GuardAmountDecreaseTest {

    private static Opportunity newOpportunity(Id id, Decimal amount) {
        return new Opportunity(
            Id = id,
            Name = 'Test Opportunity',
            Amount = amount
        );
    }

    @IsTest
    static void testAmountReducedByMoreThanHalfIsRejected() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{
            newOpportunity(oppId, 499)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            newOpportunity(oppId, 1000)
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        Opportunity updated = triggerNew[0];
        System.assert(updated.hasErrors(), 'Expected the opportunity to have an error.');
        List<ApexError> errors = updated.getErrors();
        System.assertEquals(1, errors.size(), 'Expected exactly one error on the opportunity.');
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'Expected the error message to match ERROR_MESSAGE.'
        );
    }

    @IsTest
    static void testAmountReducedByExactlyHalfIsAccepted() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{
            newOpportunity(oppId, 500)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            newOpportunity(oppId, 1000)
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(
            !triggerNew[0].hasErrors(),
            'Expected no error when Amount is reduced by exactly half.'
        );
    }

    @IsTest
    static void testAmountIncreaseIsAccepted() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{
            newOpportunity(oppId, 1500)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            newOpportunity(oppId, 1000)
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(
            !triggerNew[0].hasErrors(),
            'Expected no error when Amount increases.'
        );
    }

    @IsTest
    static void testNullPreviousAmountIsAccepted() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{
            newOpportunity(oppId, 500)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            newOpportunity(oppId, null)
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(
            !triggerNew[0].hasErrors(),
            'Expected no error when previous Amount is null.'
        );
    }

    @IsTest
    static void testMixedRecordsOnlyViolatingRecordsGetErrors() {
        Id idA = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id idB = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id idC = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{
            newOpportunity(idA, 499),  // 1000 -> 499: violates (> half reduction)
            newOpportunity(idB, 500),  // 1000 -> 500: OK (exactly half)
