        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(triggerNew[0].hasErrors(), 'First record should be flagged.');
        List<ApexError> errorsA = triggerNew[0].getErrors();
        System.assertEquals(1, errorsA.size(), 'First record should have exactly one error.');
        System.assertEquals(
